const questionCatalog = questionCatalogRu;

List<InterviewTopic> questionCatalogFor(String languageCode) =>
    languageCode == 'ru' ? questionCatalogRu : questionCatalogEn;

InterviewTopic? topicById(String id) {
  for (final topic in questionCatalog) {
    if (topic.id == id) return topic;
  }
  return null;
}
